 7	/**
 8	 * Whether an account's public score has stopped moving (IMPL-69).
 9	 *
10	 * The hourly score sample is the only growth history the host does not keep. An account whose last
11	 * several samples, spanning at least that many hours, all carry the same general score has not grown in
12	 * that time: whatever it is saving for is not arriving, so the saving is dropped and the account spends
13	 * what it holds the way a player does who notices their points have been flat all day.
14	 */
15	class StalledGrowthDetector
16	{
17	    /** Samples read, one per hour, so also the number of flat hours that counts as stalled. */
18	    private const FLAT_HOURS = 6;
19	
20	    public function stalled(int $playerId): bool
21	    {
22	        $scores = AiScoreSample::query()
23	            ->where('player_id', $playerId)
24	            ->orderByDesc('sampled_at')
25	            ->limit(self::FLAT_HOURS)
26	            ->pluck('general');
27	
28	        if ($scores->count() < self::FLAT_HOURS) {
29	            return false;
30	        }
31	
32	        return $scores->unique()->count() === 1;
33	    }
