865	    /**
866	     * The defence unit the host prices lowest that this planet's yard can build, in the count the need
867	     * is worth: the same value-to-units arithmetic the composition does, with the host's price of the
868	     * unit the doctrine cannot name here.
869	     */
870	    private function cheapestQueueableDefence(PlanetService $planet, ?DefenseNeed $need, bool $aheadOfEconomy = true): ?QueueableUnit
871	    {
872	        $best = null;
873	        $bestPrice = INF;
874	
875	        foreach (ObjectService::getDefenseObjects() as $unit) {
876	            if (! $unit instanceof UnitObject || ! $this->requirementsMet($planet, $unit)) {
877	                continue;
878	            }
879	
880	            $price = $this->metalEquivalent(ObjectService::getObjectRawPrice($unit->machine_name));
881	            if ($price <= 0.0 || $price >= $bestPrice) {
882	                continue;
883	            }
884	
885	            $best = $unit;
886	            $bestPrice = $price;
887	        }
888	
889	        if ($best === null) {
890	            return null;
891	        }
892	
893	        $amount = min(
894	            $this->affordable($planet, $best),
895	            max(self::FIRST_CARGO_AMOUNT, (int) ceil(($need?->defenceValue ?? 0.0) / $bestPrice))
896	        );
897	
898	        // The host refuses an order it cannot pay for whole, so a planet holding less than one unit's
899	        // price is left to a later login rather than sent a batch that creates no queue row.
900	        if ($amount < self::FIRST_CARGO_AMOUNT) {
901	            return null;
902	        }
903	
904	        return $this->unit($planet, $best, 'role:defense:standing:'.$best->machine_name, $amount, $aheadOfEconomy);
905	    }
906	
907	    /**
908	     * Whether this order would spend a resource the planet is saving for an economy step: a player
909	     * mines while short, and defence comes from what the economy leaves.
910	     */
911	    private function starvesSaving(PlanetService $planet, AiProfile $profile, UnitObject $unit, int $amount): bool
912	    {
913	        // A flat score means the saving is not arriving: spend instead of waiting on it (IMPL-69).
914	        if ($this->stalledGrowth->stalled($profile->player_id)) {
915	            return false;
916	        }
917	
918	        $saving = $this->buildingPlanner->savingFor($planet, $profile);
919	        if ($saving === null) {
920	            return false;
921	        }
922	
923	        $price = ObjectService::getObjectPrice($unit->machine_name, $planet);
924	        $held = $planet->getResources();
925	
926	        foreach (['metal', 'crystal', 'deuterium'] as $resource) {
927	            if ($price->{$resource}->get() > 0 && $saving->{$resource}->get() > 0
928	                && $held->{$resource}->get() - $price->{$resource}->get() * $amount < $saving->{$resource}->get()) {
929	                return true;
930	            }
931	        }
932	
933	        return false;
934	    }
935	
936	    private function metalEquivalent(Resources $resources): float
937	    {
938	        return $resources->metal->get()
939	            + self::CRYSTAL_WEIGHT * $resources->crystal->get()
940	            + self::DEUTERIUM_WEIGHT * $resources->deuterium->get();
941	    }
942	}

  280	    /**
  281	     * What this planet is saving for: the price plus reserve of the first economy step the planet is
  282	     * short of, or null when it is not saving. A player mines while short, so anything else that spends
  283	     * the same resource waits (the shipyard leaves the balance alone until the step is paid).
  284	     */
  285	    public function savingFor(PlanetService $planet, AiProfile $profile): ?Resources
  286	    {
  287	        $candidate = $this->savingCandidate($planet, $profile);
  288	        if ($candidate === null) {
  289	            return null;
  290	        }
  291	
  292	        return $this->withReserve($planet, ObjectService::getObjectPrice(ObjectService::getObjectById($candidate->buildingId)->machine_name, $planet), ReserveFloor::ECONOMY_HOURS);
  293	    }
