  295	    /** The first step in the planner's own order this planet cannot yet pay for, or null when it can pay for all of them. */
  296	    private function savingCandidate(PlanetService $planet, AiProfile $profile): ?BuildCandidate
  297	    {
  298	        foreach ($this->passes($profile) as $pass) {
  299	            foreach ($pass($planet) as $candidate) {
  300	                if ($this->refusal($planet, $candidate) === 'price plus reserve') {
  301	                    return $candidate;
  302	                }
  303	            }
  304	        }
  305	
  306	        return null;
  307	    }
