  309	    /**
  310	     * What this planet is holding resources back for, or null when it spends freely.
  311	     *
  312	     * Only a goal saver holds anything back (PERS-007). The strategy decides how the pile is spent, never
  313	     * whether the account spends at all: every other strategy leaves the balance alone, so the decision
  314	     * doctrine's spend-first rule stands for the immediate spender. The goal is the first step the planet
  315	     * cannot yet pay for -- the step it would buy the moment it could -- and no object is named here, so
  316	     * a goal it reaches is replaced by the next one with no edit.
  317	     */
  318	    private function savingsGoal(PlanetService $planet, AiProfile $profile): ?SavingsGoal
  319	    {
  320	        // The profile's own cast is the gate: a strategy the module does not manage leaves the
  321	        // balance alone, so nothing is held back and the account spends as before.
  322	        if ($profile->stockpile_strategy !== AiStockpileStrategy::GoalSaver) {
  323	            return null;
  324	        }
  325	
  326	        $candidate = $this->savingCandidate($planet, $profile);
  327	        if ($candidate === null) {
  328	            return null;
  329	        }
  330	
  331	        $machineName = ObjectService::getObjectById($candidate->buildingId)->machine_name;
  332	
  333	        return app()->makeWith(SavingsGoal::class, [
  334	            'cost' => ObjectService::getObjectPrice($machineName, $planet),
  335	            'objectId' => $candidate->buildingId,
  336	        ]);
  337	    }
  338	
  339	    /**
  340	     * Whether the planet can pay for this candidate out of what the goal leaves spendable.
  341	     *
  342	     * A saving player holds the goal's price back and spends what is left over, so a cheaper upgrade
  343	     * that would burn the reserved pile waits its turn. The goal's own purchase is the exception:
  344	     * spending the reserve is what the reserve is for.
  345	     *
  346	     * The comparison is against the price alone, because the reserve already is the margin that must
  347	     * survive the purchase: the goal was named precisely because the planet cannot yet pay its price
  348	     * plus the same floor, so spendable = available - reserved is always below that floor and a price
  349	     * plus floor again can never fit inside it. Measured that way the branch never passes and a goal
  350	     * saver stops playing entirely -- frozen on every planet until the goal is reached, which is the
  351	     * strategy deciding *whether* the account spends rather than how (PERS-007). Every other spend
  352	     * still has to clear refusal()'s price-plus-reserve gate, so the floor is not lost, only not
  353	     * charged twice against the reserve that exists to carry it.
  354	     */
  355	    private function canSpendFor(PlanetService $planet, ?SavingsGoal $goal, BuildCandidate $candidate): bool
  356	    {
  357	        if ($goal === null || $goal->covers($candidate->buildingId)) {
  358	            return true;
  359	        }
  360	
  361	        $price = ObjectService::getObjectPrice(ObjectService::getObjectById($candidate->buildingId)->machine_name, $planet);
  362	        $spendable = $goal->spendable($planet->getResources());
  363	
  364	        return $spendable->metal->get() >= $price->metal->get()
  365	            && $spendable->crystal->get() >= $price->crystal->get()
  366	            && $spendable->deuterium->get() >= $price->deuterium->get();
  367	    }
  368	
  369	    /**
  370	     * The same question for a technology, asked the way the host's research page asks it.
  371	     *
  372	     * Research is account-wide on the host's screen while its queue and its requirements are per
  373	     * planet, so the planet that answers is the planet whose laboratory carries it. Nothing here
  374	     * names a technology: the price, the requirement graph and the queue are all the host's.
  375	     */
  376	    private function queueableResearch(PlanetService $planet, BuildCandidate $candidate): ?QueueableResearch
  377	    {
  378	        $machineName = ObjectService::getObjectById($candidate->buildingId)->machine_name;
  379	
  380	        // A technology already in research anywhere on the account is not offered again: the host
  381	        // would take the row and then cancel it, so the capability is withheld instead of the
  382	        // decision being spent on a refusal.
  383	        if ($this->researchQueueService->activeResearchQueueItemCount($planet->getPlayer(), $candidate->buildingId) > 0) {
  384	            return null;
  385	        }
  386	
  387	        $queueable = !$this->researchQueueService->retrieveQueue($planet)->isQueueFull()
  388	            && ObjectService::objectRequirementsMetWithQueue($machineName, ($planet->getPlayer()?->getResearchLevel($machineName) ?? 0) + 1, $planet)
  389	            && $planet->hasResources($this->withReserve($planet, ObjectService::getObjectPrice($machineName, $planet), ReserveFloor::RESEARCH_HOURS));
  390	
  391	        if (!$queueable) {
  392	            return null;
  393	        }
  394	
  395	        return app()->makeWith(QueueableResearch::class, [
  396	            'planetId' => $planet->getPlanetId(),
  397	            'researchId' => $candidate->buildingId,
  398	            'reason' => $candidate->reason,
  399	        ]);
