```php
<?php

namespace Modules\AI\Domain\Decision;

use Modules\AI\Models\AiScoreSample;
use RuntimeException;
use Symfony\Component\Yaml\Yaml;

/**
 * Whether an account's public score has stopped moving (IMPL-69).
 *
 * The hourly score sample is the only growth history the host does not keep. An account whose last
 * several samples, spanning at least that many hours, all carry the same general score has not grown in
 * that time: whatever it is saving for is not arriving, so the hold it keeps on its balance is dropped
 * and the account spends what it holds the way a player does who notices their points have been flat
 * all day. The sample rows are the module's own copy of the host's numbers, and the window is the
 * behaviour file's, so both are retunable without an edit here.
 */
class StalledGrowthDetector
{
    private const BEHAVIOR_FILE = '/resources/behavior/growth.yaml';

    /** @var array<int, bool> one answer per account per process: a session asks once per planet per plan. */
    private array $answered = [];

    public function stalled(int $playerId): bool
    {
        return $this->answered[$playerId] ??= $this->readFlat($playerId);
    }

    private function readFlat(int $playerId): bool
    {
        $hours = $this->flatHours();

        $scores = AiScoreSample::query()
            ->where('player_id', $playerId)
            ->orderByDesc('sampled_at')
            ->limit($hours)
            ->pluck('general');

        if ($scores->count() < $hours) {
            return false;
        }

        return $scores->unique()->count() === 1;
    }

    /** How many consecutive flat hours count as stalled, read by name from the behaviour file. */
    private function flatHours(): int
    {
        $parsed = Yaml::parseFile(module_path('AI', self::BEHAVIOR_FILE));
        $hours = is_array($parsed) ? ($parsed['stalled_growth']['flat_hours'] ?? null) : null;

        if (!is_numeric($hours) || (int) $hours < 1) {
            throw new RuntimeException('growth: the file must state stalled_growth.flat_hours.');
        }

        return (int) $hours;
    }
}
```

