108	/**
109	 * Dotted key paths of a YAML document, built from indentation so a nested rule reads the same as a
110	 * flat one: "planets:" + "position:" is the rule "planet_position".
111	 *
112	 * @return list<string>
113	 */
114	function solarSystemYamlKeyPaths(string $file): array
115	{
116	    $lines = file($file, FILE_IGNORE_NEW_LINES);
117	
118	    if ($lines === false) {
119	        return [];
120	    }
121	
122	    $stack = [];
123	    $paths = [];
124	
125	    foreach ($lines as $line) {
126	        $key = solarSystemYamlLineKey($line);
127	
128	        if ($key === null) {
129	            continue;
130	        }
131	
132	        $indent = strlen($line) - strlen(ltrim($line, " \t"));
133	
134	        while ($stack !== [] && $stack[count($stack) - 1][0] >= $indent) {
135	            array_pop($stack);
136	        }
137	
138	        $prefix = implode('.', array_column($stack, 1));
139	        $paths[] = $prefix === '' ? $key : $prefix . '.' . $key;
140	        $stack[] = [$indent, $key];
141	    }
142	
143	    return $paths;
144	}
