146	function solarSystemYamlLineKey(string $line): ?string
147	{
148	    $trimmed = trim($line);
149	
150	    if ($trimmed === '' || str_starts_with($trimmed, '#')) {
151	        return null;
152	    }
153	
154	    if (str_starts_with($trimmed, '- ')) {
155	        $trimmed = trim(substr($trimmed, 2));
156	    }
157	
158	    $colon = strpos($trimmed, ':');
159	
160	    if ($colon === false) {
161	        return null;
162	    }
163	
164	    $key = trim(substr($trimmed, 0, $colon), " \t\"'");
165	
166	    return $key === '' ? null : $key;
167	}
